// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "17 Squares".

Well, sometimes there are 17 squares, but often there are more or fewer.
(Hint: The time macro in the shader code contains a comment indicating
the point in time when there are exactly 17 squares.)
The construction and deconstruction of the scene stands for the three
phases of existence. These are creation, existence, and decay.

Once again, I drew inspiration from a Japanese anime. This time, it was
the late-1980s film Grave of the Fireflies (火垂るの墓) by Studio Ghibli.
This movie depicts the horrors of World War II in Japan. It is very
emotional, so I wouldn't recommend it to anyone with a weak stomach.
*/

let theShader, dpr = Math.max(1, window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2656590/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define MN min(R.x,R.y)
#define T time // 17 squares are at (.0*time+1.1) in landscape and 1. in portrait mode
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define gold vec3(255,233,152)/255.
#define bron vec3(87,55,13)/255.
#define fcos(a) (cos(a)*S(6.3,.0,fwidth(a)))
#define hue(a) (.25+.4*fcos(2.8*(a)+vec3(0,83,21)))
#define lum(a) dot(a,vec3(.27,.71,.07))
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	vec2 w=fwidth(p);
	float t=.0, a=1., ww=max(w.x,w.y); mat2 m=mat2(cos(1.57+vec4(0,11,33,0)));
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p)*S(1.,.5,ww);
		p*=2.*m;
		a*=.5;
		ww*=2.;
	}
	return t;
}
// Returns a square with rounded corners at the given point
float rbox(vec2 p) {
	p*=p*p*p;
	return pow(dot(p,p),.125);
}
// Converts the given color into the Academy Color Encoding System color space
vec3 aces(vec3 x) {
  const float
  a=2.51,
  b=0.03,
  c=2.43,
  d=0.59,
  e=0.14;
  return clamp((x*(a*x+b))/(x*(c*x+d)+e),.0,1.);
}
// The main function of the fragment shader
void main() {
	vec2 uv=(FC-.5*R)/MN, o=vec2(1.5,2.5);
	if (R.x>R.y) o=o.yx;
	vec2 p=uv*1.125, id=clamp(.5+round(p/.25-.5),-o,o);
	p-=clamp(.5+round(p/.25-.5),-o,o)*.25;
	float d=rbox(p);
	vec3 col=vec3(0);
	float e=pow(.16/d,.8)-.2*SE(d,.12);
	col+=.125+.4*cos(1.8*(1.5+.8*e*fbm(fbm(fbm(uv*9.+T*.1)+uv*7.+10.)+uv*.5-20.))+vec3(0,83,21));
	col=mix(col,mix(gold,bron,mix(.2,.6,rnd(uv))),col);
	col*=.5*(1.+hue(rnd(id+fract(uv.y-1.5*uv.x))))*e*sqrt(SE(d,.12));
	col/=1.+exp(-col*lum(col));
	col=sqrt(col);
	id=vec2(id.x,-id.y);
	float k=3., t=mod(T*k,20.);
	if (t > 5. && t <= 15.) {
		float tt=floor(mod((T*k-5.)*3.5,35.));
		vec2 q=abs(id);
		col*=tt>=floor(q.x+q.y)?1.:.0;
	} else if (t > 15.) {
		float tt=floor(mod((T*k-20.)*5.,25.));
		vec2 q=abs(id);
		col*=tt>=floor(q.x+q.y)?.0:1.;
	} else {
		float tt=floor(mod(T*k*6.,30.));
		vec2 q=id+o+.5;
		col*=tt>=floor(q.x+q.y*(R.x>R.y?6.:4.))?1.:.0;
	}
	if (t<5.) {
		col=aces(col)/lum(col);
	}
	if (t>15.) {
		col/=lum(col);
		col=1.-col;
	}
	col=clamp(col,.08,1.);
	O=vec4(col,1);
}

